tests:
const ana = { name: 'Ana', age: 17 };
const bojan = { name: 'Bojan', age: 18 };
const cana = { name: 'Cana', age: 40 };
test({ sr: 'vraća prvu punoletnu osobu', en: 'returns the first adult' }, () => {
  expect(firstAdult([ana, bojan, cana])).toBe(bojan);
});
test({ sr: 'tačno 18 godina se računa', en: 'exactly 18 counts' }, () => {
  expect(firstAdult([bojan])).toBe(bojan);
});
test({ sr: 'nema punoletne osobe daje undefined', en: 'no adult gives undefined' }, () => {
  expect(firstAdult([ana])).toBe(undefined);
});

hiddenTests:
test('the first by order, not the oldest', () => {
  expect(firstAdult([cana, bojan])).toBe(cana);
});
test('an empty array gives undefined', () => {
  expect(firstAdult([])).toBe(undefined);
});
test('returns the same object, not a copy', () => {
  const people = [ana, bojan];
  expect(firstAdult(people)).toBe(people[1]);
});
test('only minors gives undefined, not null', () => {
  expect(firstAdult([{ name: 'X', age: 5 }, { name: 'Y', age: 17 }])).toBe(undefined);
});
test('does not change the input', () => {
  const people = [ana, bojan, cana];
  firstAdult(people);
  expect(people).toEqual([ana, bojan, cana]);
});

solutions.code:
function firstAdult(people) {
  for (const person of people) {
    if (person.age >= 18) return person;
  }
  return undefined;
}
